'use client'
import React, { useState, useRef, useEffect } from 'react'
import { Camera, Save, User, Mail, Lock, FileText, Globe, ChevronDown, Shield } from 'lucide-react'
import { useUserStore } from '../../store/userStore'
import { toast } from 'react-toastify'

const API_URL = 'http://LOCALHOST:4444'
const defaultProfileImg = 'https://cdn.intra.42.fr/users/9ae5b3303aaceb68d7a6e580c60545a4/yzoullik.jpg'

function SwitchButton({ label, checked, onChange }) {
  return (
    <div className="flex items-center justify-between w-full sm:w-auto gap-3">
      <label className="flex items-center gap-3 cursor-pointer select-none">
        <span className="text-gray-300 text-sm sm:text-base font-medium">{label}</span>
        <div className="relative">
          <input
            type="checkbox"
            className="sr-only"
            checked={checked}
            onChange={onChange}
          />
          <div
            className={`w-12 h-7 rounded-full transition-colors duration-300 ${
              checked ? 'bg-blue-400' : 'bg-gray-400'
            }`}
          ></div>
          <div
            className={`absolute top-[2px] left-[2px] w-6 h-6 bg-gray-900 rounded-full shadow-md transform transition-transform duration-300 ${
              checked ? 'translate-x-5 ' : ''
            }`}
          ></div>
        </div>
      </label>
    </div>
  )
}

const ProfileSettingsPage = () => {
  const setUser = useUserStore((state) => state.setUser)
  const fileInputRef = useRef(null)
  const [isLoading, setIsLoading] = useState(false)
  const [is2FAEnabled, setIs2FAEnabled] = useState(false)
  const [previewImage, setPreviewImage] = useState(null)

  const [formData, setFormData] = useState({
    profile_img: '',
    languages: 'en',
    username: '',
    full_name: '',
    email: '',
    bio: '',
    newPassword: '',
    confirmPassword: '',
  })

  const Userdata = {
    id_user: 1,
    username: 'yzoullik',
    full_name: 'Youssef Zoullik',
    email: 'yzoullik@example.com',
    profile_img: defaultProfileImg,
    bio: 'Just a developer trying to make it in the world.',
    auth_method: 0,
    languages: 'en',
  }

  const languages = [
    { id: 'en', label: 'English', flag: '🇬🇧' },
    { id: 'es', label: 'Spanish', flag: '🇪🇸' },
    { id: 'tz', label: 'Tamazight', flag: 'ⵣ' },
    { id: 'fr', label: 'French', flag: '🇫🇷' },
  ]
  const authMethod = Userdata?.auth_method || 0
  const isPasswordAuth = authMethod === 0
  const handleInputChange = (e) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleImageClick = () => fileInputRef.current?.click()

  const handleImageChange = (e) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload a valid image file')
      return
    }
    const reader = new FileReader()
    reader.onloadend = () => setPreviewImage(reader.result)
    reader.readAsDataURL(file)
  }

  const handleSave = async () => {
    toast.success('Profile updated successfully!')
  }

  return (
    <div className="min-h-screen w-full bg-black text-white p-4 sm:p-6 md:p-10">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-3xl sm:text-4xl font-bold mb-2">Account Settings</h1>
          <p className="text-gray-500 text-sm sm:text-base">
            Manage your profile and preferences
          </p>
        </div>

        {/* Profile Card */}
        <div className="border border-gray-700 rounded-2xl shadow-lg bg-black">
          {/* Profile Image */}
          <div className="flex flex-col items-center py-8 border-b border-gray-700 relative">
            <div
              onClick={handleImageClick}
              className="relative cursor-pointer group"
            >
              <img
                src={previewImage || Userdata.profile_img}
                alt="Profile"
                className="w-32 h-32 sm:w-36 sm:h-36 rounded-full border-2 border-gray-500 object-cover group-hover:brightness-75 transition"
              />
              <div className="absolute inset-0 bg-black bg-opacity-60 flex flex-col justify-center items-center rounded-full opacity-0 group-hover:opacity-100 transition">
                <Camera size={28} className="mb-1" />
                <span className="text-xs">Change Photo</span>
              </div>
            </div>
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              accept="image/*"
              onChange={handleImageChange}
            />
          </div>

          {/* Form */}
          <div className="p-6 sm:p-8 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Language and 2FA in the same row */}
            <div className="md:col-span-2">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Language Selector */}
                <div className="w-1/5">
                  <label
                    htmlFor="languages"
                    className="flex items-center gap-2 text-gray-400 text-sm mb-2"
                  >
                    <Globe size={18} /> Preferred Language
                  </label>
                  <div className="relative">
                    <select
                      id="languages"
                      name="languages"
                      value={formData.languages}
                      onChange={handleInputChange}
                      className="w-full bg-black border-2 border-gray-600 rounded-xl p-3 pr-10 text-sm sm:text-base text-white focus:border-white focus:ring-2 focus:ring-white appearance-none"
                    >
                      {languages.map((lang) => (
                        <option
                          key={lang.id}
                          value={lang.id}
                          className="bg-black text-white"
                        >
                          {lang.flag} {lang.label}
                        </option>
                      ))}
                    </select>
                    <ChevronDown
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400"
                      size={20}
                    />
                  </div>
                </div>

                {/* Two-Factor Authentication */}
                <div className="flex flex-col justify-end">
                 
                    <div className="flex items-center gap-2 text-gray-400">
                      <Shield size={18} />
                      <span className="text-sm sm:text-base font-medium">
                        Two-Factor Authentication
                      </span>
                    </div>
                    <SwitchButton
                      label={is2FAEnabled ? 'Enabled' : 'Disabled'}
                      checked={is2FAEnabled}
                      onChange={() => setIs2FAEnabled(!is2FAEnabled)}
                    />
                  </div>
             
              </div>
            </div>

            {/* Username */}
            <div>
              <label className="text-gray-400 text-sm mb-1 block">Username</label>
              <input
                type="text"
                name="username"
                value={formData.username}
                onChange={handleInputChange}
                placeholder="Enter username"
                className="w-full bg-black border-2 border-gray-600 rounded-xl p-3 text-white focus:border-white"
              />
            </div>

            {/* Full Name */}
            <div>
              <label className="text-gray-400 text-sm mb-1 block">Full Name</label>
              <input
                type="text"
                name="full_name"
                value={formData.full_name}
                onChange={handleInputChange}
                placeholder="Enter full name"
                className="w-full bg-black border-2 border-gray-600 rounded-xl p-3 text-white focus:border-white"
              />
            </div>

            {/* Email */}
            <div className="md:col-span-2">
              <label className="text-gray-400 text-sm mb-1 block">Email</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleInputChange}
                placeholder="Enter email"
                className="w-full bg-black border-2 border-gray-600 rounded-xl p-3 text-white focus:border-white"
              />
            </div>

            {/* Bio */}
            <div className="md:col-span-2">
              <label className="text-gray-400 text-sm mb-1 block">Bio</label>
              <textarea
                name="bio"
                rows={4}
                value={formData.bio}
                onChange={handleInputChange}
                placeholder="Tell us about yourself..."
                className="w-full bg-black border-2 border-gray-600 rounded-xl p-3 text-white focus:border-white resize-none"
              />
            </div>

            {/* Password Fields - Only show if password auth */}
            {isPasswordAuth && (
              <>
                <div>
                  <label htmlFor="newPassword" className='flex items-center gap-2 text-xs sm:text-sm font-semibold text-gray-500 mb-2'>
                    <Lock size={16} className='sm:w-5 sm:h-5' />
                    New Password
                  </label>
                  <input 
                    type="password" 
                    id="newPassword"
                    name="newPassword"
                    value={formData.newPassword}
                    onChange={handleInputChange}
                    className='w-full p-3 sm:p-3.5 border-2 border-gray-400 bg-black rounded-xl focus:ring-2 focus:ring-white focus:border-white transition-all outline-none text-white text-sm sm:text-base hover:border-white placeholder-gray-500'
                    placeholder="Enter new password"
                  />
                </div>

                <div>
                  <label htmlFor="confirmPassword" className='flex items-center gap-2 text-xs sm:text-sm font-semibold text-gray-500 mb-2'>
                    <Lock size={16} className='sm:w-5 sm:h-5' />
                    Confirm Password
                  </label>
                  <input 
                    type="password" 
                    id="confirmPassword"
                    name="confirmPassword"
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    className='w-full p-3 sm:p-3.5 border-2 border-gray-400 bg-black rounded-xl focus:ring-2 focus:ring-white focus:border-white transition-all outline-none text-white text-sm sm:text-base hover:border-white placeholder-gray-500'
                    placeholder="Confirm new password"
                  />
                </div>
              </>
            )}

            {/* OAuth Info Message */}
            {!isPasswordAuth && (
              <div className='md:col-span-2 p-4 bg-black border-2 border-gray-400 rounded-xl'>
                <p className='text-xs sm:text-sm text-gray-500 flex items-start gap-2'>
                  <Lock size={16} className='mt-0.5 flex-shrink-0' />
                  <span>
                    You signed in with <strong className='text-white'>{authMethod === 1 ? 'Google' : '42'}</strong>. Password management is not available for OAuth accounts.
                  </span>
                </p>
              </div>
            )}
          </div>

          {/* Save Button */}
          <div className="flex justify-end p-6 sm:p-8 border-t border-gray-700">
            <button
              onClick={handleSave}
              disabled={isLoading}
              className={`px-6 py-3 rounded-xl font-semibold text-sm sm:text-base transition ${
                isLoading
                ? 'bg-gray-600 cursor-not-allowed opacity-50'
                : 'bg-white text-black hover:bg-gray-500 hover:text-white active:scale-95'
              }`}
            >
              {isLoading ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

export default ProfileSettingsPage